static inline void regForwardPass(const float* x, float* out) {
  // layer 0: 15->32  ReLU
  float rh0[32];
  for (int j = 0; j < 32; j++) {
    float s = RB0[j];
    for (int k = 0; k < 15; k++) s += x[k] * RW0[k * 32 + j];
    rh0[j] = s > 0.0f ? s : 0.0f;
  }
  // layer 1: 32->16  ReLU
  float rh1[16];
  for (int j = 0; j < 16; j++) {
    float s = RB1[j];
    for (int k = 0; k < 32; k++) s += rh0[k] * RW1[k * 16 + j];
    rh1[j] = s > 0.0f ? s : 0.0f;
  }
  // layer 2: 16->8  ReLU
  float rh2[8];
  for (int j = 0; j < 8; j++) {
    float s = RB2[j];
    for (int k = 0; k < 16; k++) s += rh1[k] * RW2[k * 8 + j];
    rh2[j] = s > 0.0f ? s : 0.0f;
  }
  // layer 3: 8->2  linear
  float raw[2];
  for (int j = 0; j < 2; j++) {
    float s = RB3[j];
    for (int k = 0; k < 8; k++) s += rh2[k] * RW3[k * 2 + j];
    raw[j] = s;
  }
  // denormalize: out = raw * output_std + output_mean
  for (int i = 0; i < 2; i++) out[i] = raw[i] * REG_OUT_STD[i] + REG_OUT_MEAN[i];
}
